const base='https://www.cruise.ca/public-sites/api/site/58f45ef4-c253-43dd-b198-141872ed26be/';
const records=new Map(),queue=[];
let active=0;
export function normalizeRating(value){const score=value?.noteFloat,count=value?.totalReviews;if(!Number.isFinite(score)||score<=0||score>5||!Number.isSafeInteger(count)||count<1)return null;return {score,count,scale:5,source:'cruise.ca',checkedAt:new Date().toISOString()}}
export const ratingKey=(type,name)=>type+':'+name;
const normalized=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&(?:amp|#39|quot);/g,' ').replace(/[^a-z0-9]+/g,' ').trim();
export function reviewLinks(type,name,{company='',portId=''}={}){
  const brands={'Norwegian Cruise Line':'norwegian-ncl','Celebrity Cruises':'celebrity','MSC Cruises':'msc','Princess Cruises':'princess','Costa Cruises':'costa','Royal Caribbean':'royal-caribbean','Holland America Line':'holland-america'};
  const shipSlug=normalized(name).replaceAll(' ','-');
  const knownPort={barcelona:'https://www.cruisecritic.com/cruise/reviews/port/barcelona',rotterdam:'https://www.cruisecritic.com/memberreviews/ports/rotterdam-cruises'}[portId];
  const direct=type==='boat'&&brands[company]?'https://www.cruisecritic.com/cruise/'+brands[company]+'/'+shipSlug+'/reviews':type==='port'&&knownPort?knownPort:null;
  const critic=direct||'https://www.google.com/search?'+new URLSearchParams({q:'site:cruisecritic.com '+name+' '+company+' traveler reviews'});
  const google=type==='port'?'https://www.google.com/maps/search/?'+new URLSearchParams({api:'1',query:name+' cruise port'}):'https://www.google.com/search?'+new URLSearchParams({q:name+' '+company+' avis voyageurs'});
  return '<span class="review-links"><a href="'+critic.replaceAll('&','&amp;')+'" target="_blank" rel="noopener noreferrer">'+(direct?'Avis Cruise Critic':'Trouver sur Cruise Critic')+'</a><a href="'+google.replaceAll('&','&amp;')+'" target="_blank" rel="noopener noreferrer">'+(type==='port'?'Google Maps':'Recherche Google')+'</a></span>';
}
async function get(path){const r=await fetch(base+path,{credentials:'omit',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('Avis indisponibles');const text=await r.text();return text?JSON.parse(text):null}
export function loadRating(type,name,id){const key=ratingKey(type,name);if(records.has(key))return records.get(key);const promise=new Promise(resolve=>{queue.push(async()=>{try{let entityId=id;if(!Number.isSafeInteger(entityId)||entityId<1){const matches=await get('search/autocomplete?'+new URLSearchParams({type:type.toUpperCase(),request:name,lang:'fr'}));const match=Array.isArray(matches)?matches.find(m=>m.type===type&&normalized(m.label||'')===normalized(name)):null;entityId=match?.id}if(!Number.isSafeInteger(entityId)||entityId<1){resolve(null);return}const path='nps/summary?'+new URLSearchParams({type,entityId:String(entityId),lang:'fr'});const result=normalizeRating(await get(path));resolve(result?{...result,sourceUrl:base+path}:null)}catch{resolve(null)}});pump()});records.set(key,promise);return promise}
function pump(){while(active<3&&queue.length){active++;queue.shift()().finally(()=>{active--;pump()})}}
export function ratingMarkup(type,name,id,{compact=false,link=false}={}){return `<span class="traveler-rating ${compact?'rating-compact':''}" data-rating-type="${type}" data-rating-name="${encodeURIComponent(name||'')}" data-rating-id="${Number.isSafeInteger(id)?id:''}" data-rating-compact="${compact}" data-rating-link="${link}" title="Avis des voyageurs · cruise.ca">${compact?'★ —':'Avis voyageurs · vérification…'}</span>`}
let observer;
export function hydrateRatings(root=document){if(typeof IntersectionObserver==='undefined')return;observer??=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const el=entry.target;observer.unobserve(el);const name=decodeURIComponent(el.dataset.ratingName);loadRating(el.dataset.ratingType,name,Number(el.dataset.ratingId)).then(r=>{if(!el.isConnected)return;const compact=el.dataset.ratingCompact==='true';el.classList.toggle('rating-unavailable',!r);el.title=r?'Avis voyageurs · '+r.source+' · '+r.count+' avis · relevé le '+new Date(r.checkedAt).toLocaleDateString('fr-CA'):'Note non disponible · aucun avis vérifiable fourni par cruise.ca';if(!r){el.textContent=compact?'★ —':'Note non disponible';return}const score=r.score.toLocaleString('fr-CA',{minimumFractionDigits:1,maximumFractionDigits:1});el.textContent=compact?'★ '+score:'★ '+score+'/5 · '+r.count.toLocaleString('fr-CA')+' avis · cruise.ca';if(el.dataset.ratingLink==='true'){const a=document.createElement('a');a.href=r.sourceUrl;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Source';a.className='rating-source';el.append(' · ',a)}})}},{rootMargin:'80px'});root.querySelectorAll('[data-rating-type]:not([data-rating-observed])').forEach(el=>{el.dataset.ratingObserved='true';observer.observe(el)})}
